"""Evidence checks and current roadmap summary for complete regime coverage."""
import collections,json
from pathlib import Path
R=Path(__file__).resolve().parents[1];E=R/'reports/evidence/complete-coverage'
c=json.loads((E/'completion.json').read_text());seeds=[22,23] if c['confirmation_passed'] is not None else [22]
rows=[json.loads(l) for l in (E/'calibration.jsonl').read_text().splitlines()]
assert collections.Counter(r['fault'] for r in rows)==collections.Counter({i:20 for i in range(8)})
lines=['# Complete fault-regime coverage: results','','Twenty newly collected triple-fault incidents augment the original 140 calibration records. No previous held-out incidents enter training. This evaluates new incidents across known regimes, not unseen fault combinations.','']
checks={}
for seed in seeds:
 d=E/f'eval-{seed}';s=json.loads((d/'summary.json').read_text())['methods'];pred=json.loads((d/'predictions.json').read_text());test=[json.loads(l) for l in (d/'test.jsonl').read_text().splitlines()]
 assert len(test)==80 and collections.Counter(r['fault'] for r in test)==collections.Counter({i:10 for i in range(8)})
 assert all(r['seed']==6601+(seed-22) and r['seconds']<35 and all(f['successes']==f['requests'] for f in r['frames']) for r in test)
 assert all(json.loads((d/'audit.json').read_text()).values()) and json.loads((d/'summary.json').read_text())['checkpoint_unchanged']
 for k,v in s.items():assert v['correct']==sum(a==b for a,b in zip(pred[k],pred['target']))
 t=json.loads((E/f'training-{seed}.json').read_text())
 lines += [f"## {'Development' if seed==22 else 'Independent confirmation'}: model seed {seed}",'',f"Primary reward readout: **{s['dreamer_reward']['correct']}/80**; gate **{'PASS' if s['dreamer_reward']['gate_passed'] else 'FAIL'}**. Auxiliary: {s['dreamer_auxiliary']['correct']}/80. Telemetry: {s['raw']['correct']}/80. Training: {t['seconds']/60:.2f} minutes, 100,000 steps.",'','| Family | Reward | Auxiliary | Telemetry |','|---|---:|---:|---:|']
 for i,name in enumerate(['Healthy','CPU','Pool','Delay','CPU + delay','CPU + pool','Pool + delay','Triple']):lines.append('| '+name+' | '+' | '.join(str(s[k]['families'][str(i)]['correct'])+'/10' for k in ('dreamer_reward','dreamer_auxiliary','raw'))+' |')
 lines+=[''];checks[str(seed)]=dict(valid_incidents=80,verified_scores=True,collection_minutes=sum(r['seconds'] for r in test)/60)
if c['confirmation_passed'] is None:lines+=['Independent confirmation was skipped because the prespecified primary development gate failed. Comparators do not override that gate.','']
lines+=['Post-hoc error analysis: all three primary methods called the first healthy incident delay. Its ledger cumulative p95 was about 440 ms, while its measured batches completed in 60–70 ms. Metric counts include the two warm-up batches, and service snapshots retain samples until the next control reset. Thus elevated warm-up latency persisted into the measured observations; the specific startup cause is not proven. This row remains in the score. The shared triple miss omitted pool, and the reward readout additionally missed pool in one CPU+pool case.','','Next: define and test a consistent measurement window that excludes warm-up samples without resetting fault state or pool connections, retain startup transients as a separately evaluated scenario, and then run a fresh validation. Investigate weak pool-pressure observations rather than relabeling or dropping failed cases. Independent confirmation remains pending.','','The primary readout and gates were fixed before data collection. Passing a small batch would support the bounded demonstration, not production reliability or statistical proof of 90% per-family accuracy. Equal or worse performance than telemetry alone does not establish added value from imagined planning. A matched no-supervision ablation, broader topologies, unseen causes, LLM integration and autonomous repair remain outside this result.','','All label-isolation audits passed; checkpoint digests were unchanged during scoring. The previous deployment was restored, and no candidate was promoted. Other namespaces and repositories were untouched.','','Protocol: `reports/COMPLETE_COVERAGE_PROTOCOL.md`. Evidence: `reports/evidence/complete-coverage/`. PDF: `output/pdf/dreamerv3-complete-coverage.pdf`.']
(R/'reports/COMPLETE_COVERAGE_RESULTS.md').write_text('\n'.join(lines)+'\n');(E/'verified.json').write_text(json.dumps(checks,indent=2))
s=json.loads((E/'eval-22/summary.json').read_text())['methods']
status=f"With all eight regimes represented in training, development Dreamer scored **{s['dreamer_reward']['correct']}/80** fresh exact diagnoses versus **{s['raw']['correct']}/80** for telemetry. The primary gate **{'passed' if c['development_passed'] else 'failed'}**. "+('Independent model seed 23 '+('passed' if c['confirmation_passed'] else 'failed')+' on a separate fresh batch.' if c['confirmation_passed'] is not None else 'Independent confirmation was skipped as prespecified.')+' The existing deployment is restored. This tests known regimes, not unseen combinations. Next: fix the warm-up measurement window, then run fresh validation before independent confirmation.'
p=R/'README.md';text=p.read_text().replace('## Latest experiment — auxiliary mechanism supervision','## Latest experiment — complete fault-regime coverage\n\n'+status+'\n\n[Results](reports/COMPLETE_COVERAGE_RESULTS.md) · [Research note](output/pdf/dreamerv3-complete-coverage.pdf)\n\n## Earlier experiment — auxiliary mechanism supervision');p.write_text(text)
p=R/'MVP_PLAN.md';text=p.read_text();start=text.index('**Status:**');end=text.index('\n\n',start);p.write_text(text[:start]+'**Status:** '+status+' See [latest results](reports/COMPLETE_COVERAGE_RESULTS.md).'+text[end:])
print(json.dumps(c))
